<?php declare(strict_types=1);use FastWebsite\Core\View;$v=static fn(string$f):string=>(string)($values[$f]??'');$editing=is_int($itemId);?><section class="admin-page-heading"><div><h1><?=$editing?'Edit partnership':'Create partnership'?></h1></div><a class="button button-secondary" href="<?=View::escape($baseUrl)?>admin/engagement">Cancel</a></section><?php if($errors!==[]):?><div class="form-alert"><ul><?php foreach($errors as$e):?><li><?=View::escape($e)?></li><?php endforeach;?></ul></div><?php endif;?><form class="content-form" method="post" action="<?=View::escape($baseUrl)?>admin/engagement/partnerships<?=$editing?'/'.$itemId:''?>"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><section class="form-section"><div class="form-grid"><div class="form-field span-2"><label for="title">Partnership title *</label><input id="title" name="title" required maxlength="255" value="<?=View::escape($v('title'))?>"></div><div class="form-field"><label for="partner_id">Partner *</label><select id="partner_id" name="partner_id" required><?php foreach($partners as$p):?><option value="<?=(int)$p['id']?>"<?=$v('partner_id')===(string)$p['id']?' selected':''?>><?=View::escape($p['name'])?></option><?php endforeach;?></select></div><div class="form-field"><label for="faculty_id">Faculty *</label><select id="faculty_id" name="faculty_id"><?php foreach($faculties as$f):?><option value="<?=(int)$f['id']?>"<?=$v('faculty_id')===(string)$f['id']?' selected':''?>><?=View::escape($f['name'])?></option><?php endforeach;?></select></div><div class="form-field"><label for="partnership_type">Type</label><select id="partnership_type" name="partnership_type"><?php foreach(['mou','research','teaching','student_exchange','staff_exchange','industry','community','funding','other']as$t):?><option value="<?=$t?>"<?=$v('partnership_type')===$t?' selected':''?>><?=ucwords(str_replace('_',' ',$t))?></option><?php endforeach;?></select></div><div class="form-field"><label for="reference_number">Reference number</label><input id="reference_number" name="reference_number" maxlength="120" value="<?=View::escape($v('reference_number'))?>"></div><div class="form-field"><label for="start_date">Start date</label><input id="start_date" name="start_date" type="date" value="<?=View::escape($v('start_date'))?>"></div><div class="form-field"><label for="end_date">End date</label><input id="end_date" name="end_date" type="date" value="<?=View::escape($v('end_date'))?>"></div><div class="form-field span-2"><label for="document_id">Published document</label><select id="document_id" name="document_id"><option value="">No public document</option><?php foreach($documents as$d):?><option value="<?=(int)$d['id']?>"<?=$v('document_id')===(string)$d['id']?' selected':''?>><?=View::escape($d['title'])?></option><?php endforeach;?></select></div><div class="form-field span-2"><label for="description">Description</label><textarea id="description" name="description" rows="8"><?=View::escape($v('description'))?></textarea></div></div></section><div class="form-actions"><button class="button <?=$canPublish?'button-secondary':'button-primary'?>" name="submit_action" value="save">Save</button><?php if($canPublish):?><button class="button button-primary" name="submit_action" value="publish">Save and publish</button><?php endif;?></div></form>
